import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, a, b = map(int, data)

    pieces = [a, a, a, a, b, b]  # two doors: 4 vertical sides and 2 top sides

    # dp[mask] = minimal number of bars used to place pieces in 'mask',
    # with the current last bar having the maximal possible remaining length
    INF = 10**9
    size = 1 << 6
    dp = [(-1, -1)] * size  # (bars_used, remaining_in_current_bar)
    dp[0] = (1, n)  # start with one empty bar

    for mask in range(size):
        bars_used, rem = dp[mask]
        if bars_used == -1:
            continue
        for i in range(6):
            if not (mask & (1 << i)):
                length = pieces[i]
                nmask = mask | (1 << i)
                if length <= rem:
                    cand = (bars_used, rem - length)
                else:
                    cand = (bars_used + 1, n - length)

                cur = dp[nmask]
                if cur[0] == -1 or cand[0] < cur[0] or (cand[0] == cur[0] and cand[1] > cur[1]):
                    dp[nmask] = cand

    print(dp[size - 1][0])

if __name__ == "__main__":
